-- Упражнения книги 17, глава 19 (oVirt). Файл строит scratchpad/ovirt/builder.py; после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 19, 'ov19-host-history', 0, 'func', 'История статусов хоста', 'Модель жизни хоста. Переходы (статус, событие) → новый статус: (Installing, install_ok) → Up; (Installing, install_fail) → InstallFailed; (InstallFailed, reinstall) → Installing; (Up, no_heartbeat) → Connecting; (Connecting, heartbeat) → Up; (Connecting, retries_exhausted) → NonResponsive; (NonResponsive, heartbeat) → Up; (NonResponsive, fenced) → Connecting; (Up, requirement_failed) → NonOperational; (NonOperational, requirement_ok) → Up; (Up, maintenance) → PreparingForMaintenance; (NonOperational, maintenance) → PreparingForMaintenance; (PreparingForMaintenance, evacuated) → Maintenance; (Maintenance, activate) → Up; (Maintenance, reinstall) → Installing. Событие, для которого перехода нет, игнорируется. Напишите функцию host_history(start, events): верните список статусов, которые прошёл хост, начиная со start; в список попадает только каждая реальная смена статуса (игнорируемые события ничего не добавляют).', 'def host_history(start, events):
    pass
', 'Таблица переходов в словаре с ключом-кортежем; добавляйте новый статус в список, только если он отличается от текущего.', '{"func": "host_history", "tests": [{"args": ["Installing", []], "expected": ["Installing"]}, {"args": ["Installing", ["install_ok", "maintenance", "evacuated", "activate"]], "expected": ["Installing", "Up", "PreparingForMaintenance", "Maintenance", "Up"]}, {"args": ["Installing", ["install_fail", "reinstall", "install_ok"]], "expected": ["Installing", "InstallFailed", "Installing", "Up"]}, {"args": ["Up", ["no_heartbeat", "heartbeat", "heartbeat", "no_heartbeat", "retries_exhausted", "fenced", "heartbeat"]], "expected": ["Up", "Connecting", "Up", "Connecting", "NonResponsive", "Connecting", "Up"]}, {"args": ["Up", ["requirement_failed", "maintenance", "evacuated", "reinstall", "install_ok"]], "expected": ["Up", "NonOperational", "PreparingForMaintenance", "Maintenance", "Installing", "Up"]}, {"args": ["Maintenance", ["fenced", "no_heartbeat", "activate", "no_heartbeat", "retries_exhausted"]], "expected": ["Maintenance", "Up", "Connecting", "NonResponsive"]}, {"args": ["NonResponsive", ["retries_exhausted", "heartbeat", "requirement_failed", "requirement_ok"]], "expected": ["NonResponsive", "Up", "NonOperational", "Up"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 19, 'ov19-deploy-log', 1, 'func', 'Итог развёртывания хоста', 'Журнал развёртывания хоста — список строк. Строка задачи имеет вид "<время> TASK <имя задачи> -> <результат>": время — одно слово без пробелов, дальше слово TASK, затем имя (оно может содержать пробелы и даже символы " -> "), затем разделитель " -> " и результат. Результат должен быть одним из ok, changed, skipped, failed; разделитель берётся последний в строке. Все остальные строки (в том числе с другим результатом) игнорируются. Напишите функцию deploy_result(lines): верните кортеж (статус, имя первой упавшей задачи, число задач с результатом changed). Статус — "InstallFailed", если была хотя бы одна задача с результатом failed (имя берётся у первой такой; пустое имя допустимо); иначе "Up", если была хотя бы одна подходящая строка; иначе "Installing" с пустым именем и нулём. Задачи changed считаются по всем подходящим строкам.', 'def deploy_result(lines):
    pass
', 'line.split('' '', 2) даёт время, слово TASK и остаток; остаток разбейте методом rpartition('' -> '').', '{"func": "deploy_result", "tests": [{"args": [[]], "expected": {"__tuple__": ["Installing", "", 0]}}, {"args": [["10:00:01 TASK Gathering facts -> ok", "10:00:02 TASK Install vdsm packages -> changed", "10:00:09 TASK Request certificate -> changed", "10:00:10 TASK Enable vdsmd -> ok"]], "expected": {"__tuple__": ["Up", "", 2]}}, {"args": [["10:00:01 TASK Gathering facts -> ok", "10:00:05 TASK Install vdsm packages -> failed", "10:00:06 TASK Rollback -> changed", "10:00:07 TASK Cleanup -> failed"]], "expected": {"__tuple__": ["InstallFailed", "Install vdsm packages", 1]}}, {"args": [["PLAY [host-deploy]", "10:00:01 TASK Check disk -> skipped", "random noise -> failed", "10:00:02 TASK Configure libvirt -> changed"]], "expected": {"__tuple__": ["Up", "", 1]}}, {"args": [["10:00:01 TASK Copy a -> b -> changed", "10:00:02 TASK Copy c -> d -> failed"]], "expected": {"__tuple__": ["InstallFailed", "Copy c -> d", 1]}}, {"args": [["10:00:01 TASK Wait for host -> ok (retried 2 times)", "10:00:03 TASK Open ports -> done"]], "expected": {"__tuple__": ["Installing", "", 0]}}, {"args": [["10:00:01 TASK  -> failed", "10:00:02 TASK Next -> changed"]], "expected": {"__tuple__": ["InstallFailed", "", 1]}}, {"args": [["TASK Only two fields", "12:00 TASK Start vdsmd -> changed", "12:01 TASK Start vdsmd -> changed", "12:02 TASK Final check -> ok"]], "expected": {"__tuple__": ["Up", "", 2]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 19, 'ov19-vdsm-client', 2, 'func', 'Разбор вызова vdsm-client', 'Напишите функцию parse_vdsm_client(cmd), которая разбирает командную строку вида "vdsm-client <Namespace> <verb> key=value ...". Строка делится по пробелам (любое число пробелов, кавычек нет). Первое слово должно быть vdsm-client, дальше обязательны пространство имён и глагол, иначе верните None. Каждый остальной аргумент — key=value, где разделение идёт по первому знаку =; значение может содержать = и быть пустым, а вот пустой ключ или отсутствие = дают None. Значения преобразуются: ровно true и false — в булевы; строка из десятичных ASCII-цифр с необязательным одним минусом впереди (минус и цифры, одни цифры, но не просто "-") — в целое число; всё остальное остаётся строкой (в том числе "1.5"). Если ключ повторяется, побеждает последний. Верните кортеж (namespace, verb, params), где params — словарь.', 'def parse_vdsm_client(cmd):
    pass
', 'split() без аргументов; tok.partition(''='') даёт ключ, знак и значение; для числа уберите один ведущий ''-'' и проверьте isdigit().', '{"func": "parse_vdsm_client", "tests": [{"args": ["vdsm-client Host getStats"], "expected": {"__tuple__": ["Host", "getStats", {}]}}, {"args": ["vdsm-client VM getStats vmID=5f1c"], "expected": {"__tuple__": ["VM", "getStats", {"vmID": "5f1c"}]}}, {"args": ["  vdsm-client   Host   setMOMPolicy   enabled=true   limit=1024  "], "expected": {"__tuple__": ["Host", "setMOMPolicy", {"enabled": true, "limit": 1024}]}}, {"args": ["vdsm-client StorageDomain getInfo storagedomainID=a=b offset=-5 ratio=1.5 flag=false"], "expected": {"__tuple__": ["StorageDomain", "getInfo", {"storagedomainID": "a=b", "offset": -5, "ratio": "1.5", "flag": false}]}}, {"args": ["vdsm-client Host"], "expected": null}, {"args": ["vdsm-client Host getStats broken"], "expected": null}, {"args": ["vdsm-client Host getStats =x"], "expected": null}, {"args": ["client Host getStats"], "expected": null}, {"args": ["vdsm-client VM destroy vmID=1 vmID=2"], "expected": {"__tuple__": ["VM", "destroy", {"vmID": 2}]}}, {"args": ["vdsm-client Host x v=- w=--3 z="], "expected": {"__tuple__": ["Host", "x", {"v": "-", "w": "--3", "z": ""}]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 19, 'ov19-fencing-candidate', 3, 'func', 'Когда хост становится кандидатом', 'Менеджер опрашивает хост и записывает результаты опросов: polls — список пар (время в секундах, ok), упорядоченный по времени. Хост становится кандидатом на ограждение в момент опроса, когда сразу выполнены два условия: подряд идущих неудач (ok равно False) накопилось не меньше attempts, и с времени первой неудачи этой серии прошло не меньше timeout секунд. Удачный опрос сбрасывает серию. Напишите функцию fencing_candidate(polls, attempts, timeout): верните время первого опроса, на котором хост стал кандидатом, или -1, если этого не произошло.', 'def fencing_candidate(polls, attempts, timeout):
    pass
', 'Храните счётчик серии и время её начала; на удачном опросе обнуляйте счётчик.', '{"func": "fencing_candidate", "tests": [{"args": [[{"__tuple__": [0, false]}, {"__tuple__": [30, false]}, {"__tuple__": [60, false]}], 2, 60], "expected": 60}, {"args": [[{"__tuple__": [0, true]}, {"__tuple__": [30, true]}], 2, 60], "expected": -1}, {"args": [[{"__tuple__": [0, false]}, {"__tuple__": [30, false]}, {"__tuple__": [60, true]}, {"__tuple__": [90, false]}, {"__tuple__": [120, false]}, {"__tuple__": [150, false]}], 2, 60], "expected": 150}, {"args": [[{"__tuple__": [0, false]}, {"__tuple__": [10, false]}, {"__tuple__": [20, false]}, {"__tuple__": [30, false]}], 3, 0], "expected": 20}, {"args": [[{"__tuple__": [5, false]}], 1, 0], "expected": 5}, {"args": [[{"__tuple__": [0, false]}, {"__tuple__": [30, false]}, {"__tuple__": [60, false]}, {"__tuple__": [90, false]}], 5, 60], "expected": -1}, {"args": [[{"__tuple__": [0, false]}, {"__tuple__": [30, true]}, {"__tuple__": [45, false]}, {"__tuple__": [60, false]}, {"__tuple__": [105, false]}], 2, 60], "expected": 105}, {"args": [[], 2, 60], "expected": -1}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 19, 'ov19-host-verdict', 4, 'func', 'Вердикт по хосту', 'Менеджер проверяет хост по порядку и останавливается на первой проблеме. Хост описан словарём с полями installed (bool), reachable (bool), missing_networks (список имён сетей), cpu_ok (bool), storage_ok (bool). Правила по порядку: если не installed — ("InstallFailed", "install failed"); если не reachable — ("NonResponsive", "unreachable"); если список missing_networks не пуст — ("NonOperational", "network: " + имена, отсортированные и соединённые запятой без пробелов); если не cpu_ok — ("NonOperational", "cpu"); если не storage_ok — ("NonOperational", "storage"); иначе ("Up", "ok"). Напишите функцию host_verdict(h), возвращающую такой кортеж.', 'def host_verdict(h):
    pass
', 'Цепочка if с ранним return; для сетей '',''.join(sorted(...)).', '{"func": "host_verdict", "tests": [{"args": [{"installed": true, "reachable": true, "missing_networks": [], "cpu_ok": true, "storage_ok": true}], "expected": {"__tuple__": ["Up", "ok"]}}, {"args": [{"installed": false, "reachable": false, "missing_networks": [], "cpu_ok": true, "storage_ok": true}], "expected": {"__tuple__": ["InstallFailed", "install failed"]}}, {"args": [{"installed": true, "reachable": false, "missing_networks": ["db"], "cpu_ok": false, "storage_ok": true}], "expected": {"__tuple__": ["NonResponsive", "unreachable"]}}, {"args": [{"installed": true, "reachable": true, "missing_networks": ["storage", "backup"], "cpu_ok": false, "storage_ok": false}], "expected": {"__tuple__": ["NonOperational", "network: backup,storage"]}}, {"args": [{"installed": true, "reachable": true, "missing_networks": [], "cpu_ok": false, "storage_ok": false}], "expected": {"__tuple__": ["NonOperational", "cpu"]}}, {"args": [{"installed": true, "reachable": true, "missing_networks": [], "cpu_ok": true, "storage_ok": false}], "expected": {"__tuple__": ["NonOperational", "storage"]}}, {"args": [{"installed": true, "reachable": true, "missing_networks": ["only"], "cpu_ok": true, "storage_ok": true}], "expected": {"__tuple__": ["NonOperational", "network: only"]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 19, 'ov19-evacuate', 5, 'func', 'Эвакуация хоста', 'Хост уходит в обслуживание. vms — список машин на нём, каждая словарь с полями name, mem (МБ) и pinned (bool); targets — словарь имя хоста → свободная память (МБ) на других хостах. Закреплённые машины (pinned) перенести нельзя, они остаются на месте. Остальные обрабатываются в порядке убывания mem, при равенстве — по имени. Каждую кладут на хост с наибольшей свободной памятью среди тех, где памяти хватает (mem не больше свободной); при равенстве — на хост с меньшим именем; затем память хоста уменьшается. Если подходящего хоста нет, машина остаётся. Напишите функцию evacuate(vms, targets): верните кортеж (статус, размещение, оставшиеся). Статус — "Maintenance", если не осталось ни одной машины, иначе "PreparingForMaintenance"; размещение — словарь имя машины → хост; оставшиеся — отсортированный список имён.', 'def evacuate(vms, targets):
    pass
', 'Отсортируйте movable по (-mem, name); для выбора хоста min(подходящие, key=lambda n: (-free[n], n)).', '{"func": "evacuate", "tests": [{"args": [[{"name": "a", "mem": 4, "pinned": false}, {"name": "b", "mem": 8, "pinned": false}, {"name": "c", "mem": 2, "pinned": false}], {"h2": 10, "h3": 10}], "expected": {"__tuple__": ["Maintenance", {"b": "h2", "a": "h3", "c": "h3"}, []]}}, {"args": [[], {"h2": 1}], "expected": {"__tuple__": ["Maintenance", {}, []]}}, {"args": [[{"name": "big", "mem": 16, "pinned": false}, {"name": "mid", "mem": 6, "pinned": false}, {"name": "small", "mem": 2, "pinned": false}], {"h2": 8, "h3": 7}], "expected": {"__tuple__": ["PreparingForMaintenance", {"mid": "h2", "small": "h3"}, ["big"]]}}, {"args": [[{"name": "pin", "mem": 4, "pinned": true}, {"name": "x", "mem": 4, "pinned": false}], {"h2": 10}], "expected": {"__tuple__": ["PreparingForMaintenance", {"x": "h2"}, ["pin"]]}}, {"args": [[{"name": "a", "mem": 5, "pinned": false}, {"name": "b", "mem": 5, "pinned": false}, {"name": "c", "mem": 5, "pinned": false}], {"h2": 10, "h3": 4}], "expected": {"__tuple__": ["PreparingForMaintenance", {"a": "h2", "b": "h2"}, ["c"]]}}, {"args": [[{"name": "a", "mem": 3, "pinned": false}, {"name": "b", "mem": 3, "pinned": false}], {}], "expected": {"__tuple__": ["PreparingForMaintenance", {}, ["a", "b"]]}}, {"args": [[{"name": "m2", "mem": 4, "pinned": false}, {"name": "m1", "mem": 4, "pinned": false}, {"name": "m3", "mem": 4, "pinned": false}], {"hb": 8, "ha": 8}], "expected": {"__tuple__": ["Maintenance", {"m1": "ha", "m2": "hb", "m3": "ha"}, []]}}, {"args": [[{"name": "s1", "mem": 3, "pinned": false}, {"name": "s2", "mem": 3, "pinned": false}, {"name": "s3", "mem": 3, "pinned": false}, {"name": "s4", "mem": 3, "pinned": false}], {"h2": 7, "h3": 7}], "expected": {"__tuple__": ["Maintenance", {"s1": "h2", "s2": "h3", "s3": "h2", "s4": "h3"}, []]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 19, 'ov19-fence-proxy', 6, 'func', 'Выбор прокси для ограждения', 'Команду ограждения выполняет другой хост. hosts — список словарей с полями name, status, cluster, dc; target — имя хоста, который нужно оградить; order — список областей поиска из "cluster", "dc", "other_dc". Область "cluster": хосты того же центра данных и того же кластера; "dc": того же центра данных, но другого кластера; "other_dc": другого центра данных. Подходят только хосты со статусом "Up", кроме самого target. Области перебираются в порядке order, берётся первая, где есть подходящие, и в ней хост с наименьшим именем. Областей, не указанных в order, не существует. Напишите функцию pick_fence_proxy(hosts, target, order): верните имя прокси или пустую строку, если подходящего нет или если хоста target нет в списке.', 'def pick_fence_proxy(hosts, target, order):
    pass
', 'Найдите описание target, затем для каждой области соберите имена подходящих хостов и возьмите min.', '{"func": "pick_fence_proxy", "tests": [{"args": [[{"name": "a1", "status": "Up", "cluster": "c1", "dc": "dc1"}, {"name": "a2", "status": "Up", "cluster": "c1", "dc": "dc1"}, {"name": "a3", "status": "NonResponsive", "cluster": "c1", "dc": "dc1"}, {"name": "b1", "status": "Up", "cluster": "c2", "dc": "dc1"}, {"name": "b2", "status": "Maintenance", "cluster": "c2", "dc": "dc1"}, {"name": "z1", "status": "Up", "cluster": "c9", "dc": "dc2"}, {"name": "z0", "status": "Up", "cluster": "c9", "dc": "dc2"}], "a3", ["cluster", "dc", "other_dc"]], "expected": "a1"}, {"args": [[{"name": "a1", "status": "Up", "cluster": "c1", "dc": "dc1"}, {"name": "a2", "status": "Up", "cluster": "c1", "dc": "dc1"}, {"name": "a3", "status": "NonResponsive", "cluster": "c1", "dc": "dc1"}, {"name": "b1", "status": "Up", "cluster": "c2", "dc": "dc1"}, {"name": "b2", "status": "Maintenance", "cluster": "c2", "dc": "dc1"}, {"name": "z1", "status": "Up", "cluster": "c9", "dc": "dc2"}, {"name": "z0", "status": "Up", "cluster": "c9", "dc": "dc2"}], "a3", ["dc", "cluster"]], "expected": "b1"}, {"args": [[{"name": "a1", "status": "Up", "cluster": "c1", "dc": "dc1"}, {"name": "a2", "status": "Up", "cluster": "c1", "dc": "dc1"}, {"name": "a3", "status": "NonResponsive", "cluster": "c1", "dc": "dc1"}, {"name": "b1", "status": "Up", "cluster": "c2", "dc": "dc1"}, {"name": "b2", "status": "Maintenance", "cluster": "c2", "dc": "dc1"}, {"name": "z1", "status": "Up", "cluster": "c9", "dc": "dc2"}, {"name": "z0", "status": "Up", "cluster": "c9", "dc": "dc2"}], "a3", ["other_dc", "cluster"]], "expected": "z0"}, {"args": [[{"name": "a3", "status": "NonResponsive", "cluster": "c1", "dc": "dc1"}, {"name": "a2", "status": "Maintenance", "cluster": "c1", "dc": "dc1"}, {"name": "b1", "status": "Up", "cluster": "c2", "dc": "dc1"}], "a3", ["cluster", "dc", "other_dc"]], "expected": "b1"}, {"args": [[{"name": "a3", "status": "NonResponsive", "cluster": "c1", "dc": "dc1"}, {"name": "a2", "status": "Maintenance", "cluster": "c1", "dc": "dc1"}, {"name": "b1", "status": "Up", "cluster": "c2", "dc": "dc1"}], "a3", ["cluster"]], "expected": ""}, {"args": [[{"name": "a1", "status": "Up", "cluster": "c1", "dc": "dc1"}, {"name": "a2", "status": "Up", "cluster": "c1", "dc": "dc1"}, {"name": "a3", "status": "NonResponsive", "cluster": "c1", "dc": "dc1"}, {"name": "b1", "status": "Up", "cluster": "c2", "dc": "dc1"}, {"name": "b2", "status": "Maintenance", "cluster": "c2", "dc": "dc1"}, {"name": "z1", "status": "Up", "cluster": "c9", "dc": "dc2"}, {"name": "z0", "status": "Up", "cluster": "c9", "dc": "dc2"}], "z1", ["cluster", "dc", "other_dc"]], "expected": "z0"}, {"args": [[{"name": "a1", "status": "Up", "cluster": "c1", "dc": "dc1"}, {"name": "a2", "status": "Up", "cluster": "c1", "dc": "dc1"}, {"name": "a3", "status": "NonResponsive", "cluster": "c1", "dc": "dc1"}, {"name": "b1", "status": "Up", "cluster": "c2", "dc": "dc1"}, {"name": "b2", "status": "Maintenance", "cluster": "c2", "dc": "dc1"}, {"name": "z1", "status": "Up", "cluster": "c9", "dc": "dc2"}, {"name": "z0", "status": "Up", "cluster": "c9", "dc": "dc2"}], "z1", ["cluster"]], "expected": "z0"}, {"args": [[{"name": "a1", "status": "Up", "cluster": "c1", "dc": "dc1"}, {"name": "a2", "status": "Up", "cluster": "c1", "dc": "dc1"}, {"name": "a3", "status": "NonResponsive", "cluster": "c1", "dc": "dc1"}, {"name": "b1", "status": "Up", "cluster": "c2", "dc": "dc1"}, {"name": "b2", "status": "Maintenance", "cluster": "c2", "dc": "dc1"}, {"name": "z1", "status": "Up", "cluster": "c9", "dc": "dc2"}, {"name": "z0", "status": "Up", "cluster": "c9", "dc": "dc2"}], "nobody", ["cluster", "dc"]], "expected": ""}, {"args": [[{"name": "c1", "status": "Up", "cluster": "x", "dc": "d"}, {"name": "c2", "status": "Up", "cluster": "y", "dc": "d"}], "c1", []], "expected": ""}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 19, 'ov19-fencing-policy', 7, 'func', 'Политика ограждения', 'Напишите функцию decide_fencing(policy, lease_age, statuses, bricks_up). policy — словарь настроек кластера; отсутствующие ключи означают: enabled — True, skip_live_lease, skip_connectivity, skip_gluster_bricks — False, threshold — 50. lease_age — сколько секунд назад неотвечающий хост продлевал аренду на хранилище (None, если неизвестно); statuses — список статусов всех хостов кластера, включая неотвечающий; bricks_up — работают ли кирпичи Gluster. Проверки по порядку, первая сработавшая возвращает ("skip", причина): enabled ложно — "fencing disabled"; skip_live_lease и lease_age не None и lease_age строго меньше 80 — "live lease"; skip_connectivity и statuses не пуст и доля хостов со статусом "NonResponsive" в процентах не меньше threshold (сравнивайте целыми числами: 100 * плохих >= threshold * всего) — "connectivity"; skip_gluster_bricks и bricks_up — "gluster bricks up". Если ничего не сработало, верните ("fence", "").', 'def decide_fencing(policy, lease_age, statuses, bricks_up):
    pass
', 'policy.get(ключ, значение по умолчанию); проверки идут цепочкой if с return в нужном порядке.', '{"func": "decide_fencing", "tests": [{"args": [{}, null, ["Up", "Up", "NonResponsive", "Up"], false], "expected": {"__tuple__": ["fence", ""]}}, {"args": [{"enabled": false}, 500, ["Up", "Up", "NonResponsive", "Up"], false], "expected": {"__tuple__": ["skip", "fencing disabled"]}}, {"args": [{"skip_live_lease": true}, 79, ["Up", "Up", "NonResponsive", "Up"], false], "expected": {"__tuple__": ["skip", "live lease"]}}, {"args": [{"skip_live_lease": true}, 80, ["Up", "Up", "NonResponsive", "Up"], false], "expected": {"__tuple__": ["fence", ""]}}, {"args": [{"skip_live_lease": true}, null, ["Up", "Up", "NonResponsive", "Up"], false], "expected": {"__tuple__": ["fence", ""]}}, {"args": [{"skip_live_lease": false}, 5, ["Up", "Up", "NonResponsive", "Up"], false], "expected": {"__tuple__": ["fence", ""]}}, {"args": [{"skip_connectivity": true}, null, ["Up", "Up", "NonResponsive", "Up"], false], "expected": {"__tuple__": ["fence", ""]}}, {"args": [{"skip_connectivity": true, "threshold": 25}, null, ["Up", "Up", "NonResponsive", "Up"], false], "expected": {"__tuple__": ["skip", "connectivity"]}}, {"args": [{"skip_connectivity": true, "threshold": 75}, null, ["NonResponsive", "NonResponsive", "Up", "Up"], false], "expected": {"__tuple__": ["fence", ""]}}, {"args": [{"skip_connectivity": true}, null, ["NonResponsive", "NonResponsive", "Up", "Up"], false], "expected": {"__tuple__": ["skip", "connectivity"]}}, {"args": [{"skip_connectivity": true}, null, [], false], "expected": {"__tuple__": ["fence", ""]}}, {"args": [{"skip_gluster_bricks": true}, null, ["Up", "Up", "NonResponsive", "Up"], true], "expected": {"__tuple__": ["skip", "gluster bricks up"]}}, {"args": [{"skip_gluster_bricks": true}, null, ["Up", "Up", "NonResponsive", "Up"], false], "expected": {"__tuple__": ["fence", ""]}}, {"args": [{"skip_live_lease": true, "skip_connectivity": true, "skip_gluster_bricks": true, "threshold": 25}, 10, ["Up", "Up", "NonResponsive", "Up"], true], "expected": {"__tuple__": ["skip", "live lease"]}}, {"args": [{"skip_connectivity": true, "skip_gluster_bricks": true, "threshold": 100}, 200, ["Up", "Up", "NonResponsive", "Up"], true], "expected": {"__tuple__": ["skip", "gluster bricks up"]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 19, 'ov19-fence-run', 8, 'func', 'Ход ограждения', 'Смоделируйте ограждение. Напишите функцию fence_run(soft_ok, agents). Сначала всегда выполняется мягкое ограждение: в журнал добавляется "soft". Если soft_ok истинно, верните (журнал, "recovered"). Иначе, если agents пуст (управления питанием нет), верните (журнал, "manual_confirm"). Иначе агенты перебираются по порядку, каждый — кортеж (имя, stop_ok, start_ok): для каждого в журнал добавляется "off:" + имя, и если его stop_ok истинно, перебор прекращается, а выбранным становится этот агент. Если ни один не выключил хост, верните (журнал, "failed"). После выключения в журнал добавляется "on:" + имя того же агента; если его start_ok истинно, результат "rebooted", иначе "powered_off". Верните кортеж (список журнала, результат).', 'def fence_run(soft_ok, agents):
    pass
', 'Заведите список log и переменную chosen; после цикла проверьте, найден ли агент.', '{"func": "fence_run", "tests": [{"args": [true, [{"__tuple__": ["ipmi1", true, true]}]], "expected": {"__tuple__": [["soft"], "recovered"]}}, {"args": [true, []], "expected": {"__tuple__": [["soft"], "recovered"]}}, {"args": [false, []], "expected": {"__tuple__": [["soft"], "manual_confirm"]}}, {"args": [false, [{"__tuple__": ["ipmi1", true, true]}]], "expected": {"__tuple__": [["soft", "off:ipmi1", "on:ipmi1"], "rebooted"]}}, {"args": [false, [{"__tuple__": ["ipmi1", false, true]}, {"__tuple__": ["ilo2", true, true]}]], "expected": {"__tuple__": [["soft", "off:ipmi1", "off:ilo2", "on:ilo2"], "rebooted"]}}, {"args": [false, [{"__tuple__": ["ipmi1", false, true]}, {"__tuple__": ["ilo2", false, true]}]], "expected": {"__tuple__": [["soft", "off:ipmi1", "off:ilo2"], "failed"]}}, {"args": [false, [{"__tuple__": ["ipmi1", true, false]}, {"__tuple__": ["ilo2", true, true]}]], "expected": {"__tuple__": [["soft", "off:ipmi1", "on:ipmi1"], "powered_off"]}}, {"args": [false, [{"__tuple__": ["apc", true, true]}, {"__tuple__": ["ipmi1", true, true]}]], "expected": {"__tuple__": [["soft", "off:apc", "on:apc"], "rebooted"]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 19, 'ov19-kdump-wait', 9, 'func', 'Ждать ли дамп ядра', 'Если включена интеграция kdump, менеджер слушает сообщения хоста. messages — список троек (время, имя хоста, вид) в произвольном порядке; вид — "started", "progress" или "done". Напишите функцию kdump_decision(messages, host, now, timeout). Учитываются только сообщения хоста host со временем не позже now. Если таких нет, верните "fence". Иначе возьмите самое позднее по времени. Если его вид "done", верните "treat_as_rebooted". Если с его времени прошло не больше timeout секунд (now - время <= timeout), верните "wait", иначе "fence".', 'def kdump_decision(messages, host, now, timeout):
    pass
', 'Отфильтруйте сообщения, возьмите max по времени и сравните kind и разницу now - t.', '{"func": "kdump_decision", "tests": [{"args": [[], "h1", 100, 60], "expected": "fence"}, {"args": [[{"__tuple__": [100, "h1", "started"]}, {"__tuple__": [130, "h1", "progress"]}, {"__tuple__": [110, "h2", "started"]}, {"__tuple__": [150, "h1", "done"]}, {"__tuple__": [300, "h3", "progress"]}, {"__tuple__": [200, "h2", "progress"]}], "h1", 140, 60], "expected": "wait"}, {"args": [[{"__tuple__": [100, "h1", "started"]}, {"__tuple__": [130, "h1", "progress"]}, {"__tuple__": [110, "h2", "started"]}, {"__tuple__": [150, "h1", "done"]}, {"__tuple__": [300, "h3", "progress"]}, {"__tuple__": [200, "h2", "progress"]}], "h1", 200, 60], "expected": "treat_as_rebooted"}, {"args": [[{"__tuple__": [100, "h1", "started"]}, {"__tuple__": [130, "h1", "progress"]}, {"__tuple__": [110, "h2", "started"]}, {"__tuple__": [150, "h1", "done"]}, {"__tuple__": [300, "h3", "progress"]}, {"__tuple__": [200, "h2", "progress"]}], "h2", 250, 60], "expected": "wait"}, {"args": [[{"__tuple__": [100, "h1", "started"]}, {"__tuple__": [130, "h1", "progress"]}, {"__tuple__": [110, "h2", "started"]}, {"__tuple__": [150, "h1", "done"]}, {"__tuple__": [300, "h3", "progress"]}, {"__tuple__": [200, "h2", "progress"]}], "h2", 261, 60], "expected": "fence"}, {"args": [[{"__tuple__": [100, "h1", "started"]}, {"__tuple__": [130, "h1", "progress"]}, {"__tuple__": [110, "h2", "started"]}, {"__tuple__": [150, "h1", "done"]}, {"__tuple__": [300, "h3", "progress"]}, {"__tuple__": [200, "h2", "progress"]}], "h2", 150, 60], "expected": "wait"}, {"args": [[{"__tuple__": [100, "h1", "started"]}, {"__tuple__": [130, "h1", "progress"]}, {"__tuple__": [110, "h2", "started"]}, {"__tuple__": [150, "h1", "done"]}, {"__tuple__": [300, "h3", "progress"]}, {"__tuple__": [200, "h2", "progress"]}], "h3", 290, 60], "expected": "fence"}, {"args": [[{"__tuple__": [100, "h1", "started"]}, {"__tuple__": [130, "h1", "progress"]}, {"__tuple__": [110, "h2", "started"]}, {"__tuple__": [150, "h1", "done"]}, {"__tuple__": [300, "h3", "progress"]}, {"__tuple__": [200, "h2", "progress"]}], "h4", 290, 60], "expected": "fence"}, {"args": [[{"__tuple__": [100, "h1", "started"]}, {"__tuple__": [130, "h1", "progress"]}, {"__tuple__": [110, "h2", "started"]}, {"__tuple__": [150, "h1", "done"]}, {"__tuple__": [300, "h3", "progress"]}, {"__tuple__": [200, "h2", "progress"]}], "h1", 120, 10], "expected": "fence"}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 19, 'ov19-restart-ha', 10, 'func', 'Перезапуск HA-машин', 'Хост огражден, нужно перезапустить его высокодоступные машины. vms — список словарей с полями name, prio (целое, больше значит важнее), mem (МБ) и group (строка антиаффинити-группы или пустая строка); hosts — словарь имя хоста → свободная память (МБ). Машины обрабатываются по убыванию prio, при равенстве — по имени. Для каждой перебираются хосты в алфавитном порядке, и берётся первый, где свободной памяти хватает (mem не больше свободной) и, если group не пуста, ещё не стоит ни одной машины той же группы, размещённой в этом запуске. Память выбранного хоста уменьшается. Если подходящего хоста нет, машина попадает в список ожидающих. Напишите функцию restart_ha(vms, hosts): верните кортеж (размещение, ожидающие), где размещение — словарь имя машины → хост, а ожидающие — список имён в порядке обработки.', 'def restart_ha(vms, hosts):
    pass
', 'Ведите для каждого хоста множество уже стоящих групп; сортируйте vms по (-prio, name), хосты — sorted(free).', '{"func": "restart_ha", "tests": [{"args": [[{"name": "web1", "prio": 2, "mem": 4, "group": "web"}, {"name": "web2", "prio": 2, "mem": 4, "group": "web"}, {"name": "db", "prio": 3, "mem": 8, "group": ""}], {"h1": 10, "h2": 10}], "expected": {"__tuple__": [{"db": "h1", "web1": "h2"}, ["web2"]]}}, {"args": [[], {"h1": 1}], "expected": {"__tuple__": [{}, []]}}, {"args": [[{"name": "a", "prio": 1, "mem": 6, "group": ""}, {"name": "b", "prio": 3, "mem": 6, "group": ""}, {"name": "c", "prio": 2, "mem": 6, "group": ""}], {"h1": 6, "h2": 6}], "expected": {"__tuple__": [{"b": "h1", "c": "h2"}, ["a"]]}}, {"args": [[{"name": "w1", "prio": 2, "mem": 2, "group": "g"}, {"name": "w2", "prio": 2, "mem": 2, "group": "g"}, {"name": "w3", "prio": 2, "mem": 2, "group": "g"}], {"h1": 10, "h2": 10}], "expected": {"__tuple__": [{"w1": "h1", "w2": "h2"}, ["w3"]]}}, {"args": [[{"name": "x", "prio": 1, "mem": 5, "group": "g"}, {"name": "y", "prio": 1, "mem": 5, "group": "g"}, {"name": "z", "prio": 1, "mem": 5, "group": ""}], {"h1": 5, "h2": 5, "h3": 5}], "expected": {"__tuple__": [{"x": "h1", "y": "h2", "z": "h3"}, []]}}, {"args": [[{"name": "big", "prio": 1, "mem": 20, "group": ""}], {"h1": 10}], "expected": {"__tuple__": [{}, ["big"]]}}, {"args": [[{"name": "l", "prio": 1, "mem": 3, "group": ""}, {"name": "h", "prio": 3, "mem": 3, "group": ""}, {"name": "m", "prio": 2, "mem": 3, "group": ""}], {"h2": 3, "h1": 3}], "expected": {"__tuple__": [{"h": "h1", "m": "h2"}, ["l"]]}}, {"args": [[{"name": "a", "prio": 2, "mem": 1, "group": "g1"}, {"name": "b", "prio": 2, "mem": 1, "group": "g2"}, {"name": "c", "prio": 2, "mem": 1, "group": "g1"}, {"name": "d", "prio": 2, "mem": 1, "group": "g2"}], {"n1": 10, "n2": 10}], "expected": {"__tuple__": [{"a": "n1", "b": "n1", "c": "n2", "d": "n2"}, []]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (17, 19, 'ov19-rolling-upgrade', 11, 'func', 'Плавное обновление кластера', 'Смоделируйте последовательное обновление. hosts — словарь имя → (число ВМ, ёмкость в ВМ). Порядок обновления определяется один раз в начале: по возрастанию числа ВМ, при равенстве по имени. Для каждого хоста h по очереди: свободное место на остальных хостах — сумма (ёмкость − текущее число ВМ) по всем хостам, кроме h. Если оно меньше числа ВМ на h, обновление останавливается и h называется блокирующим. Иначе машины h переезжают на остальные хосты: хосты берутся в алфавитном порядке, на каждый кладётся min(свободное место, оставшиеся машины). Число ВМ на h становится 0, h считается обновлённым и остаётся в работе, принимая машины при следующих шагах. Напишите функцию rolling_upgrade(hosts): верните кортеж (список обновлённых хостов в порядке обновления, имя блокирующего хоста или пустая строка).', 'def rolling_upgrade(hosts):
    pass
', 'Храните два словаря: vms и cap; порядок вычислите заранее и не пересчитывайте.', '{"func": "rolling_upgrade", "tests": [{"args": [{"h1": {"__tuple__": [4, 10]}, "h2": {"__tuple__": [4, 10]}, "h3": {"__tuple__": [4, 10]}}], "expected": {"__tuple__": [["h1", "h2", "h3"], ""]}}, {"args": [{"h1": {"__tuple__": [0, 10]}}], "expected": {"__tuple__": [["h1"], ""]}}, {"args": [{"h1": {"__tuple__": [5, 10]}, "h2": {"__tuple__": [5, 10]}}], "expected": {"__tuple__": [["h1", "h2"], ""]}}, {"args": [{"h1": {"__tuple__": [8, 10]}, "h2": {"__tuple__": [8, 10]}, "h3": {"__tuple__": [2, 10]}}], "expected": {"__tuple__": [["h3", "h1", "h2"], ""]}}, {"args": [{"a": {"__tuple__": [3, 4]}, "b": {"__tuple__": [3, 4]}, "c": {"__tuple__": [3, 4]}}], "expected": {"__tuple__": [[], "a"]}}, {"args": [{"a": {"__tuple__": [6, 8]}, "b": {"__tuple__": [1, 8]}, "c": {"__tuple__": [6, 8]}}], "expected": {"__tuple__": [["b", "a", "c"], ""]}}, {"args": [{"x": {"__tuple__": [2, 4]}, "y": {"__tuple__": [2, 4]}}], "expected": {"__tuple__": [["x", "y"], ""]}}, {"args": [{"n1": {"__tuple__": [0, 5]}, "n2": {"__tuple__": [5, 5]}}], "expected": {"__tuple__": [["n1", "n2"], ""]}}, {"args": [{"a": {"__tuple__": [1, 3]}, "b": {"__tuple__": [2, 3]}, "c": {"__tuple__": [3, 3]}}], "expected": {"__tuple__": [["a", "b", "c"], ""]}}]}');
